-- 설정이 끼워 넣는다

@Configuration
public class ProxyConfig {

    @Bean
    public OrderService orderService(LogTrace trace) {
        OrderServiceImpl target = new OrderServiceImpl(orderRepository(trace));
        return new OrderServiceProxy(target, trace);       // 프록시를 등록한다
    }
}

